---@class UIMazeBagItemNode
---@field choose                        	UnityEngine.RectTransform               
---@field item                          	UnityEngine.RectTransform                                          
local UIMazeBagItemNode = Class("UIMazeBagItemNode")
function UIMazeBagItemNode:__init() 
    self._data = nil
end

function UIMazeBagItemNode:__delete()
    self._data = nil
end

function UIMazeBagItemNode:Awake()
end

function UIMazeBagItemNode:Start()
end

function UIMazeBagItemNode:Refresh(data, clickCb)
    if not data then
        return
    end
    self._data = data
    self._clickCb = clickCb

    local itemGo = self.item.transform:Find("item")
    if not itemGo then
        if IsNull(self.loader) then
            self.loader = CS.Engine.Modules.ResourceModule.LoadBundleSync("Prefabs/Common/GoodNode.prefab", nil, true)
        end
        if self.loader.IsSuccess then
            itemGo = CfUtils.InstantiateGo(self.loader.ResultObject, self.item)
        end
        if itemGo then
            itemGo.name = "item"
        end
    end
    if itemGo then
        itemGo.transform.localPosition = Vector3(0,0,0)
    end
    
    CfUtils.RefeshGoodGo(itemGo, self._data.id, self._data.num, 0.7, Constants.IDArea.Maze, function()
        if self._clickCb then
            self._clickCb(self.controller.gameObject, self._data.id)
        end
    end)
end

function UIMazeBagItemNode:RefreshChoose(isTrue)
    KTool.SetActive(self.choose, isTrue)
end

function UIMazeBagItemNode:OnSelect()
    if self._clickCb then
        self._clickCb()
    end
end

function UIMazeBagItemNode:OnDestroy()
    if not isNull(self.loader) then
        self.loader:Release(true)
        self.loader = nil
    end
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIMazeBagItemNode
